		// The create-editor avatar's 0x737A6DF9 FullChar snapshot ("Bigboy") - 8001 bytes of opaque snapshot body,
		// held as an embedded resource (CreateEditorAvatarSnapshot.bin) rather than a 56 KB inline byte[] literal.
		private static readonly byte[] EditorAvatarSnapshot = LoadEmbeddedResource("Faolan.CreateEditorAvatarSnapshot.bin");

		private static byte[] LoadEmbeddedResource(string name)
		{
			using var stream = typeof(CreateFlowService).Assembly.GetManifestResourceStream(name)
				?? throw new InvalidOperationException($"embedded resource '{name}' not found");
			using var buffer = new MemoryStream();
			stream.CopyTo(buffer);
			return buffer.ToArray();
		}

		// The 18 galley scene-prop dynels the create-editor initial burst streams, in retail send order. Each is a
		// WorldObjects row on the editor map (4000), matched by captured handle and built byte-exact via
		// WorldObjectBuilder (see LoadEditorSceneDynels + CreateEditorSceneDynelTests). The client also renders the
		// galley from its own RDB on the MapChange; retail streams these so their handles are server-known.
		private static readonly uint[] EditorSceneDynelHandles =
		[
			0x0002A7EF, 0x0002A7FA, 0x0002A7ED, 0x0002A7EE, 0x0002A7F0, 0x0002A7F1, 0x0002A7F2, 0x0002A7F3, 0x0002A7F4,
			0x0002A7F5, 0x0002A7F6, 0x0002A7F7, 0x0002A7F8, 0x0002A7F9, 0x0002A7FB, 0x0002A7FC, 0x0002A7FD, 0x0002A7FE,
		];

		// The editor map's scene-prop WorldObjects, keyed by captured handle. Null when no DB is available.
		private static async Task<Dictionary<uint, WorldObject>> LoadEditorSceneDynels(IDatabaseRepository database)
		{
			if (database == null)
				return null;

			var rows = new Dictionary<uint, WorldObject>();
			foreach (var o in await database.GetWorldObjects(StartingData.EditorMapId))
				rows.TryAdd(o.CapturedHandle, o);

			return rows;
		}
		// Originally generated by Captures/scripts/gen_createworld_burst.py from
		// Hoxxling_mage-heraldofxotli_create_modified_all_sliders-very_long_loading_screen-chat_message_before_exit.json, // since HAND-REFACTORED (Endpoints.EndpointBytes + named opcodes + decoded records constructed via their
		// codecs) - the generator now writes to /tmp and will NOT clobber this file, so edit it directly.
		// The post-creation WORLD entry (intro cutscene: shipwreck/drowning -> beach -> Kalanthes ->
		// ApproachCasilda), captured from the hoxxling world connection (:7012). Every reference to the
		// captured character instance 0x01316E71 is written as the live client instance `id`; NPC/dynel
		// handles (e.g. Kalanthes 0x000535A0... actually capture-specific) are kept verbatim so each
		// spawn handle stays consistent with the scry message that binds it. Delivered to match retail's
		// pacing: chunk 0 (SCENE) on the world Hello, then one chunk per client cutscene trigger
		// (ClientLoadingDone, StartScript, StartScript, Move, IntroDone).
		// Chunk S->C packet counts: [324, 12, 39, 65, 100, 64].

		// The world-entry GameActionListIIR (0xF508F4C1) numeric action record for dynel 0xCF0D (delivered to
		// frame `id`); header CONSTRUCTED via GameActionListCodec, the opaque action tail rides verbatim (#190).
		private static readonly byte[] CreateWorldEntryActionTail =
		[
			0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x09, 0x00, 0x00, 0x00, 0x00, 0x00, ];

		// The small fixed-grammar avatar/NPC stat records the world-entry burst streams - constructed via
		// CreateEditorRecordBuilder (was verbatim byte-arrays), each byte-exact-locked by CreateEditorRecordTests.
		// `frame` is the receiving player instance; `handle` is the entity the record is about (the player `id` for
		// the avatar, a captured NPC handle for a creature). GameAgent sub is 0x08 on the world connection.
		private static Task StatIir(INetworkClient client, uint frame, uint handle, byte flag, uint statId, uint value) =>
			new PacketStream()
				.WriteHeader(Endpoints.EndpointBytes(Endpoints.GameAgentType, 0x08), Endpoints.EndpointBytes(Endpoints.GameInterfaceType, frame), GameInterfaceDispatchOpcodes.DispatchPassBlob)
				.WriteArrayUInt32Length(s => s.WriteUInt32(GameServer0X2000Opcodes.StatIIR).WriteArray(CreateEditorRecordBuilder.BuildStatIir(EntityClass.Character, handle, flag, statId, value)))
				.SendAsync(client);

