		// The stable remoteformat text for a {stock_N} phrase, or false if we have no capture of it.
		internal static bool TryGetStockPhraseText(string stockKey, out byte[] textBytes)
		{
			return StockPhraseRemoteFormats.TryGetValue(stockKey, out textBytes);
		}

		// Parse a c2s PlayStockphraseAsSubtitle (0x205E) request:
		//   [ProtoID npcId (u32 type, u32 instance)][String: u16 len + bytes "{stock_N}"][u32 threadCtx]
		// Returns false if the body is malformed.
		internal static bool TryParsePlayStockphraseRequest(ReadOnlySpan<byte> body, out string stockKey, out uint threadContext)
		{
			stockKey = null;
			threadContext = 0;
			if (body.Length < 8 + 2 + 4)
				return false;

			int strLen = BinaryPrimitives.ReadUInt16BigEndian(body.Slice(8, 2));
			var tcOffset = 10 + strLen;
			if (tcOffset + 4 > body.Length)
				return false;

			stockKey = System.Text.Encoding.Latin1.GetString(body.Slice(10, strLen));
			threadContext = BinaryPrimitives.ReadUInt32BigEndian(body.Slice(tcOffset, 4));
			return true;
		}

		// Build the s2c ReceivedStockPhraseText (0x205D) body: [u32 threadCtx][u16 textLen][text].
		internal static byte[] BuildReceivedStockPhraseBody(uint threadContext, byte[] textBytes)
		{
			var body = new byte[4 + 2 + textBytes.Length];
			BinaryPrimitives.WriteUInt32BigEndian(body.AsSpan(0, 4), threadContext);
			BinaryPrimitives.WriteUInt16BigEndian(body.AsSpan(4, 2), (ushort)textBytes.Length);
			textBytes.CopyTo(body.AsSpan(6));
			return body;
		}

		// Inbound handler for the client's stock-phrase request. Answers with the mapped remoteformat so the
		// client-side subtitle command completes instead of timing out after 60 s (#234 speech). Unknown stock
		// phrases (a cutscene we have no capture for) are logged and NOT answered here - surface the gap rather
		// than feed the client a wrong line (a fabricated key would show garbled text).
		[Obsolete("FROM SCRATCH")]
		internal async Task HandlePlayStockphraseAsSubtitle(INetworkClient client, byte[] requestBody)
		{
			if (!TryParsePlayStockphraseRequest(requestBody, out var stockKey, out var threadContext))
			{
				_logger.LogWarning("PlayStockphraseAsSubtitle: could not parse request body ({Len} bytes)", requestBody.Length);
				return;
			}

			if (!StockPhraseRemoteFormats.TryGetValue(stockKey, out var textBytes))
			{
				_logger.LogWarning("PlayStockphraseAsSubtitle: no remoteformat for stock phrase {Key} (tc=0x{Tc:X8}) - client will time out; add it to StockPhraseRemoteFormats from a capture", stockKey, threadContext);
				return;
			}

			var id = client.Session.Account.ClientInstance;
			await new PacketStream()
				.WriteHeader(
					Endpoints.EndpointBytes(Endpoints.GameCharAgentType, 0x08),
					Endpoints.EndpointBytes(Endpoints.GameCharInterfaceType, id),
					GameCharInterfaceDispatchOpcodes.DispatchReceivedStockPhraseText)
				.WriteArray(BuildReceivedStockPhraseBody(threadContext, textBytes))
				.SendAsync(client);

			_logger.LogInformation("PlayStockphraseAsSubtitle: answered {Key} (tc=0x{Tc:X8}) for client {Id} (#234 cutscene speech)", stockKey, threadContext, id);
		}

		private static readonly byte[] RetailCreateEditorPostReadyAckSender = Endpoints.EndpointBytes(Endpoints.GameCharAgentProjectType, 0x59);

		private static uint GetRetailCreateEditorPostReadyAckStatus(uint requestId)
		{
			return requestId == 0x0009FF95
				? 0x00000000u
				: 0x00000002u;
		}

		internal static Task SendRetailCreateEditorPostReadyAck(INetworkClient client, uint requestId)
		{
			return new PacketStream()
				.WriteHeader(RetailCreateEditorPostReadyAckSender, client.Endpoint(Endpoints.GameCharInterfaceProjectType), GameInterfaceDispatchOpcodes.DispatchPassBlob)
				.WriteUInt32(0x0000C350)
				.WriteUInt32(requestId)
				.WriteUInt32(GetRetailCreateEditorPostReadyAckStatus(requestId))
				.SendAsync(client);
		}

		// The racial CHARACTER-TEMPLATE choice list the creation editor reads (Male/Female/StygianSlaver ->
		// template ids 50000:65525x), delivered on two GameActionListIIR (0xF508F4C1) records for dynel 0xD00C.
		// The two captured variants differ ONLY in the leading action-id word; the property-map action-tail
		// grammar is still opaque (#190) so it rides verbatim, while the record HEADER is constructed via
		// GameActionListCodec.BuildBody (construct-don't-replay - see SendGameActionListRecord).
		private static readonly byte[] CreateEditorTemplateChoiceActionTailA =
		[
			0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x09, 0x00, 0x39, 0xBF, 0x93, 0x00, 0x50, 			0x4D, 0x61, 0x6C, 0x65, 0x54, 0x65, 0x6D, 0x70, 0x6C, 0x61, 0x74, 0x65, 0x3D, 0x35, 0x30, 0x30, 0x30, 0x30, 			0x3A, 0x36, 0x35, 0x35, 0x32, 0x35, 0x32, 0x3B, 0x46, 0x65, 0x6D, 0x61, 0x6C, 0x65, 0x54, 0x65, 0x6D, 0x70, 			0x6C, 0x61, 0x74, 0x65, 0x3D, 0x35, 0x30, 0x30, 0x30, 0x30, 0x3A, 0x36, 0x35, 0x35, 0x32, 0x35, 0x33, 0x3B, 			0x53, 0x74, 0x79, 0x67, 0x69, 0x61, 0x6E, 0x53, 0x6C, 0x61, 0x76, 0x65, 0x72, 0x3D, 0x35, 0x30, 0x30, 0x30, 			0x30, 0x3A, 0x36, 0x35, 0x35, 0x32, 0x35, 0x34, 0x00, 0x00, 0x00, 0x00, 0x00, 		];

		private static readonly byte[] CreateEditorTemplateChoiceActionTailB =
		[
			0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x09, 0x00, 0x01, 0x9D, 0xD1, 0x00, 0x50, 			0x4D, 0x61, 0x6C, 0x65, 0x54, 0x65, 0x6D, 0x70, 0x6C, 0x61, 0x74, 0x65, 0x3D, 0x35, 0x30, 0x30, 0x30, 0x30, 			0x3A, 0x36, 0x35, 0x35, 0x32, 0x35, 0x32, 0x3B, 0x46, 0x65, 0x6D, 0x61, 0x6C, 0x65, 0x54, 0x65, 0x6D, 0x70, 			0x6C, 0x61, 0x74, 0x65, 0x3D, 0x35, 0x30, 0x30, 0x30, 0x30, 0x3A, 0x36, 0x35, 0x35, 0x32, 0x35, 0x33, 0x3B, 			0x53, 0x74, 0x79, 0x67, 0x69, 0x61, 0x6E, 0x53, 0x6C, 0x61, 0x76, 0x65, 0x72, 0x3D, 0x35, 0x30, 0x30, 0x30, 			0x30, 0x3A, 0x36, 0x35, 0x35, 0x32, 0x35, 0x34, 0x00, 0x00, 0x00, 0x00, 0x00, 		];

		// Emits a GameActionListIIR (0xF508F4C1) carrier for `dynel`, delivered to frame `id`. The fixed record
		// header (subop/type/Head/four/one, decoded 570/570) is CONSTRUCTED via GameActionListCodec.BuildBody and
		// the still-opaque property-map action tail rides verbatim; the carrier length is computed from the body.
		private static Task SendGameActionListRecord(INetworkClient client, byte agentSub, uint id, uint dynel, byte[] actionTail)
		{
			var body = GameActionListCodec.BuildBody(id, dynel, 0u, actionTail);
			return new PacketStream()
				.WriteHeader(Endpoints.EndpointBytes(Endpoints.GameAgentType, agentSub), Endpoints.EndpointBytes(Endpoints.GameInterfaceType, id), GameInterfaceDispatchOpcodes.DispatchPassBlob)
				.WriteArrayUInt32Length(body)
				.SendAsync(client);
		}

		// Verbatim replay of the fixed tail of the retail create-editor post-ready follow-up from
		// Captures/account-stricken998-character-create-no-worldenter.json (rows 198-199, 203-204).
		// The leading 0x0009FF92-0x0009FF96 ack packets are generated dynamically from the request ids the
		// client actually sends so the live flow can advance even when it stalls before all 5 retail requests.

		internal static async Task SendRetailCreateEditorPostReadyBurst(INetworkClient client, IReadOnlyList<uint> requestIds)
		{
			foreach (var requestId in requestIds)
				await SendRetailCreateEditorPostReadyAck(client, requestId);

			var id = client.Session.Account.ClientInstance;
			await new PacketStream()
				.WriteHeader(Endpoints.EndpointBytes(Endpoints.GameCharAgentType, 0x59), Endpoints.EndpointBytes(Endpoints.GameCharInterfaceType, id), GameCharInterfaceDispatchOpcodes.DispatchValidResurrectionSpots)
				.WriteArray(0x43, 0xA7, 0x40, 0x00, 0x43, 0x14, 0x66, 0x66, 0x44, 0x25, 0x4C, 0xCD, 0x00, 0x00, 0x07, 0xE2, 0x43, 0xA7, 0x40, 0x00, 0x43, 0x14, 0x66, 0x66, 0x44, 0x25, 0x4C, 0xCD, 0x00, 0x00, 0xC7, 0x9E, 0x00, 0x00, 0x0F, 0xAA, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x64, 0x00)
				.SendAsync(client);
			await new PacketStream()
				.WriteHeader(Endpoints.EndpointBytes(Endpoints.GameAgentType, 0x59), Endpoints.EndpointBytes(Endpoints.GameInterfaceType, id), GameInterfaceDispatchOpcodes.DispatchPassBlob)
				.WriteArrayUInt32Length(s => s.WriteUInt32(GameServer0X2000Opcodes.CharInPlayIIR).WriteArray(CreateEditorRecordBuilder.BuildCharInPlayIir(id)))
				.SendAsync(client);
			await SendGameActionListRecord(client, 0x59, id, 0xD00Cu, CreateEditorTemplateChoiceActionTailA);
			await SendGameActionListRecord(client, 0x59, id, 0xD00Cu, CreateEditorTemplateChoiceActionTailB);

			// After the post-ready editor handoff, retail streams the character-creation script burst
			// (rows 274-331) that actually launches the Slave Galley creation scene via the
			// 0xA36D3B74 "NEW_character_creation" remoteformat. Without it the playfield loads (audio)
			// but the editor never appears (black screen).
			await SendRetailCreateEditorCreationScriptBurst(client);
		}

		private readonly ILogger _logger;
		private readonly IDatabaseRepository _database;

		// The live world simulation (owns the connected players' authoritative entities + zone model). Used by the
		// cutscene actor-binding (LiveNpcHandle) to re-address the destiny cinematic to OUR live Kalanthes.
		private readonly WorldSimulation _simulation;

		// The listener's burst-less world entry (Login/BurstlessWorldEntry.cs) - the constructed live-char world the
		// create-flow enters before the destiny cutscene overlay. Injected as a seam (shared with the login replay).
		private readonly Func<INetworkClient, uint, Task> _sendBurstlessWorldEntry;

		// Character ids that have just been named in the create-editor and are about to open their FIRST world
		// connection (the second GameServer connection, after the 0x2002 enter-world handoff). Added when the name is
		// committed (HandleCommandPacket TheNameIs) and consumed by the listener's world Hello via
		// TryConsumePendingCreateWorldEntry, which is how that connection is recognised as the create-world entry (and
		// given the intro/cutscene) rather than a normal login. Static because the editor and world connections are
		// different sessions but hit the same listener/service instance; ConcurrentDictionary-as-set because it is
		// mutated from different connection threads (add on one connection, consume on the reconnect). Value unused.
		private static readonly ConcurrentDictionary<uint, byte> PendingCreateWorldEntry = new ConcurrentDictionary<uint, byte>();

		public CreateFlowService(ILogger logger, IDatabaseRepository database, WorldSimulation simulation, Func<INetworkClient, uint, Task> sendBurstlessWorldEntry)
		{
			_logger = logger;
			_database = database;
			_simulation = simulation;
			_sendBurstlessWorldEntry = sendBurstlessWorldEntry;
		}

		// Consumes (removes) a pending create-world-entry marker for `clientInstance`, returning true if one was set.
		// The listener's world Hello calls this to recognise the post-creation world connection (and skip the helper
		// auth), then take the create-world entry path; consuming it means a later normal login doesn't re-trigger the intro.
		internal static bool TryConsumePendingCreateWorldEntry(uint clientInstance)
		{
			return PendingCreateWorldEntry.TryRemove(clientInstance, out _);
		}

		// The post-creation WORLD connection: the second (world) connection opened after the 0x2002 enter-world
		// handoff, flagged in the Hello handler. Distinguishes it from the editor connection and from a normal
		// existing-character login so the intro/cutscene bursts only fire there.
		private static bool IsCreateWorldConnection(INetworkClient client)
		{
			return client.Session.IsCreateWorldSession && client.Session.Character?.Name != null;
		}

		// Server->client conversation family for the creator 0x2000 traffic (GameAgent type, conversation id 0x0C).
		internal static readonly byte[] MorphAckSender = Endpoints.EndpointBytes(Endpoints.GameAgentType, 0x0C);

		// The create-editor 0x2000 receiver: the player object (GameInterfaceType) addressed to this session's
		// client instance. Built as a typed ProtoEndpoint so the type+instance can't drift (the old hardcoded
		// receiver baked in 0x021662C8; see Endpoints / ProtoEndpointGoldenTests).
		internal static byte[] Receiver(INetworkClient client)
		{
			return client.Endpoint(Endpoints.GameInterfaceType);
		}
	}
}
